/* @autogenerated */
import { applyBulkEdit } from './bulk-edit.model';

describe('applyBulkEdit', () => {
  it('replaces fields and applies string operations', () => {
    const result = applyBulkEdit({ name: 'North', address: 'Road' }, [
      { field: 'name', operation: 'replace', value: 'West' },
      { field: 'address', operation: 'prefix', value: '12 ' },
    ]);
    expect(result).toEqual({ name: 'West', address: '12 Road' });
  });

  it('applies arithmetic operations and clears optional values', () => {
    const result = applyBulkEdit({ count: 5, note: 'old' }, [
      { field: 'count', operation: 'add', value: 3 },
      { field: 'note', operation: 'clear', value: '' },
    ]);
    expect(result.count).toBe(8);
    expect(result.note).toBeUndefined();
    expect(applyBulkEdit({ count: 5 }, [{ field: 'count', operation: 'multiply', value: 2 }])).toEqual({ count: 10 });
  });

  it('sets boolean, enum and relationship fields', () => {
    const updated = applyBulkEdit({ active: false, status: 'open', client: { $ref: 'client-1' } }, [
      { field: 'active', operation: 'setTrue', value: true },
      { field: 'status', operation: 'replace', value: 'closed' },
      { field: 'client', operation: 'setNull', value: null },
    ]);
    expect(updated.active).toBeTrue();
    expect(updated.status).toBe('closed');
    expect((updated as any).client).toBeNull();
    expect(applyBulkEdit({ active: true }, [{ field: 'active', operation: 'setFalse', value: false }])).toEqual({
      active: false,
    });
  });
});
